// Valida a entrada e reduz o payload antes da IA.
const e=$json||{},p=e.performance,t=e.tendencia;
if(!p||!t)return[{json:{status_pacote:'PACOTE_INCOMPLETO',motivo:'São necessários os blocos performance e tendencia.'}}];
if(p.status_motor!=='OK')return[{json:{status_pacote:'SEM_PERFORMANCE',motivo:p.mensagem||'Motor de Performance não retornou OK.'}}];
if(t.status_tendencia!=='OK')return[{json:{status_pacote:'SEM_TENDENCIA',motivo:t.mensagem||'Motor de Tendência não retornou OK.'}}];
const lim=(v,n=5)=>Array.isArray(v)?v.slice(0,n):[];
const compacto=o=>{if(!o||typeof o!=='object')return o;const s={};for(const[k,v]of Object.entries(o)){if(v===null||v===undefined)continue;if(['string','number','boolean'].includes(typeof v))s[k]=v;}return s;};
const pacote={data_referencia:p.data_referencia||t.data_referencia||'',performance:{investimento_total:p.investimento_total??null,conversas_iniciadas:p.conversas_iniciadas??null,custo_medio_por_conversa:p.custo_medio_por_conversa??null,score_tecnico_medio:p.score_tecnico_medio??null,quantidade_registros:p.quantidade_registros??null,melhores_resultados:lim(p.melhores_resultados).map(compacto),resultados_para_atencao:lim(p.resultados_para_atencao).map(compacto)},tendencia:{quantidade_objetos:t.quantidade_objetos??null,prioridade_fadiga:t.prioridade_fadiga??null,fadiga_alta:lim(t.fadiga_alta).map(compacto),fadiga_moderada:lim(t.fadiga_moderada).map(compacto),observar:lim(t.observar).map(compacto),melhora:lim(t.melhora).map(compacto),dados_insuficientes:lim(t.dados_insuficientes).map(compacto)}};
return[{json:{status_pacote:'OK',pacote_analise:pacote,tamanho_aproximado:JSON.stringify(pacote).length}}];

// Mantém o JSON auditável e monta o texto enviado ao modelo.
if($json.status_pacote!=='OK')return items;
const dados=JSON.stringify($json.pacote_analise,null,2);
return[{json:{...$json,prompt_analise:`Analise o pacote abaixo. Os cálculos já foram feitos pelos motores determinísticos.

PACOTE:
${dados}

Entregue resumo executivo, saúde da conta, até 5 prioridades, oportunidades, riscos, hipóteses de teste mensuráveis e o que não fazer agora. Não invente fatos ausentes.`}}];

// Aplica uma última camada determinística à saída da IA.
const b=$json.output??$json,arr=v=>Array.isArray(v)?v:[];const permitidas=new Set(['MANTER','OBSERVAR','REVISAR_CRIATIVO','REVISAR_PUBLICO','REVISAR_OFERTA','TESTAR_VARIACAO','CANDIDATO_ESCALA','REDUZIR_EXPOSICAO']);
const prioridades=arr(b.prioridades).slice(0,5).map((x,i)=>({prioridade:Number(x.prioridade||i+1),nivel:String(x.nivel||'Não informado'),nome:String(x.nome||'Não informado'),diagnostico:String(x.diagnostico||''),evidencias:arr(x.evidencias).slice(0,4).map(String),acao_recomendada:permitidas.has(x.acao_recomendada)?x.acao_recomendada:'OBSERVAR',motivo:String(x.motivo||''),prazo_reavaliacao_dias:Math.max(1,Math.min(30,Number(x.prazo_reavaliacao_dias||3)))})).sort((a,b)=>a.prioridade-b.prioridade);
return[{json:{status_analise_ia:'OK',analise_ia:{resumo_executivo:String(b.resumo_executivo||''),saude_conta:String(b.saude_conta||'dados_insuficientes'),confianca_analise:String(b.confianca_analise||'baixa'),prioridades,oportunidades:arr(b.oportunidades).slice(0,5),riscos:arr(b.riscos).slice(0,5),hipoteses_teste:arr(b.hipoteses_teste).slice(0,4),nao_fazer:arr(b.nao_fazer).slice(0,5)}}}];

// Converte o JSON estruturado em briefing humano sem alterar a análise.
if($json.status_analise_ia!=='OK')return items;const a=$json.analise_ia,b=[];b.push(`ANÁLISE IA META ADS
Saúde da conta: ${String(a.saude_conta).toUpperCase()}
Confiança: ${String(a.confianca_analise).toUpperCase()}

${a.resumo_executivo}`);if(a.prioridades.length)b.push('PRIORIDADES
'+a.prioridades.map(p=>`${p.prioridade}. ${p.nome} — ${p.acao_recomendada}
${p.diagnostico}
Evidências: ${p.evidencias.join(' | ')}
Reavaliar em: ${p.prazo_reavaliacao_dias} dia(s)`).join('

'));if(a.oportunidades.length)b.push('OPORTUNIDADES
'+a.oportunidades.map(x=>`- ${x.nome}: ${x.oportunidade}`).join('
'));if(a.riscos.length)b.push('RISCOS
'+a.riscos.map(x=>`- ${x.nome}: ${x.risco}`).join('
'));if(a.hipoteses_teste.length)b.push('HIPÓTESES DE TESTE
'+a.hipoteses_teste.map(x=>`- ${x.hipotese}
  Mudança: ${x.mudanca}
  Métrica: ${x.metrica_primaria} | Janela: ${x.janela_avaliacao_dias} dia(s)`).join('
'));if(a.nao_fazer.length)b.push('NÃO FAZER AGORA
'+a.nao_fazer.map(x=>`- ${x}`).join('
'));return[{json:{...$json,briefing_gestor:b.join('

')}}];
